ownCheck(BancoBrasil\ApiOwnNumber::input($intent)===$intent,'typed intent exact');foreach(['new_reference'=>['',null,123,'lower',' SPACE','SPACE ','A B','A_B','A/B',"A\nB",str_repeat('A',16),'ÁB'],'previous_reference'=>[null,'CRM1 ','A_B'],'contract_confirmed'=>[null,1,true,'0']]as$field=>$bad)foreach($bad as$value)ownReject(fn()=>BancoBrasil\ApiOwnNumber::input(array_replace($intent,[$field=>$value])),'reject invalid '.$field);
